import struct
from typing import Dict, List, Any

# generated by Gemini

# Define the 4-byte Attached Sync Marker (ASM)
ASM_PATTERN = b'\x1a\xcf\xfc\x1d'

# Format string for the 14-byte HK_NOMINAL payload
# >  = Big-Endian
# I  = 4-byte uint32 (Timestamp)
# B  = 1-byte uint8  (Battery Mode)
# H  = 2-byte uint16 (Battery Voltage)
# H  = 2-byte uint16 (Solar Panel Current)
# h  = 2-byte int16  (CPU Temperature - signed to handle sub-zero)
# H  = 2-byte uint16 (Available Flash Storage)
# B  = 1-byte uint8  (System Status Flags)
HK_FORMAT = ">IBHHhHB"


def decode_payload(apid: int, payload_bytes: bytes) -> Any:
    """Decodes raw payload bytes based on known APID definitions."""
    if apid == 50:  # SYSLOG
        try:
            return payload_bytes.decode('ascii', errors='replace').strip()
        except Exception:
            return "[Error: Malformed ASCII Log]"
            
    elif apid == 100:  # HK_NOMINAL
        if len(payload_bytes) != 14:
            return f"[Error: Expected 14 bytes for HK, got {len(payload_bytes)}]"
        try:
            fields = struct.unpack(HK_FORMAT, payload_bytes)
            return {
                "Timestamp": fields[0],
                "Battery_Mode": fields[1],
                "Battery_Voltage_mV": fields[2],
                "Solar_Current_mA": fields[3],
                "CPU_Temp_C": fields[4],
                "Flash_Storage_KB": fields[5],
                "Status_Flags": bin(fields[6])
            }
        except Exception as e:
            return f"[Error decoding HK packet: {e}]"
            
    elif apid == 200:  # ADCS_STATUS
        return {"Raw_Bytes_Hex": payload_bytes.hex(), "Status": "Decode TBD (8-byte fixed)"}
        
    return {"Raw_Bytes_Hex": payload_bytes.hex(), "Status": "Unknown Corrupted APID"}


def process_noisy_asm_stream(file_path: str) -> Dict[str, List[Dict[str, Any]]]:
    """
    Synchronizes on ASM sequences in a noisy stream, validates CCSDS packets,
    and extracts structurally sound payloads.
    """
    with open(file_path, "rb") as f:
        stream = f.read()

    total_bytes = len(stream)
    cursor = 0
    metrics = {"valid_packets": 0, "corrupted_frames": 0, "unknown_apids": 0}
    
    # Store processed outputs by mnemonic
    extracted_data = {
        "SYSLOG": [],
        "HK_NOMINAL": [],
        "ADCS_STATUS": [],
        "UNKNOWN": []
    }

    print(f"Beginning ingestion of stream ({total_bytes} total bytes)...")

    while True:
        # Find the next occurrence of the ASM pattern starting from the current cursor position
        asm_index = stream.find(ASM_PATTERN, cursor)
        
        # If no more ASMs are found in the remaining bytes, exit loop
        if asm_index == -1:
            break
            
        # Ensure there are at least 10 bytes left to read the ASM + full 6-byte header
        if asm_index + 10 > total_bytes:
            break

        # Parse the 6-byte primary header sitting immediately after the ASM
        header_start = asm_index + 4
        header_bytes = stream[header_start : header_start + 6]
        w1, w2, w3 = struct.unpack(">HHH", header_bytes)

        # Decode header fields using bitwise shifting
        version = (w1 >> 13) & 0x07
        apid = w1 & 0x07FF
        sequence_count = w2 & 0x3FFF
        
        # CCSDS definition: data length field value equals total payload bytes minus 1
        payload_length = w3 + 1
        total_packet_length = 4 + 6 + payload_length  # ASM + Header + Payload

        # Check if entire expected packet sits cleanly within the remaining stream boundaries
        if asm_index + total_packet_length > total_bytes:
            metrics["corrupted_frames"] += 1
            cursor = asm_index + 4  # Skip past this ASM sequence and look for the next one
            continue

        # Structural Heuristic Validation
        is_valid_ccsds = (version == 0)
        
        if is_valid_ccsds:
            # Isolate the exact payload bytes
            payload_start = header_start + 6
            payload_bytes = stream[payload_start : payload_start + payload_length]
            
            # Map APID to its designated mnemonic group
            if apid == 50:
                mnemonic = "SYSLOG"
            elif apid == 100:
                mnemonic = "HK_NOMINAL"
            elif apid == 200:
                mnemonic = "ADCS_STATUS"
            else:
                mnemonic = "UNKNOWN"
                metrics["unknown_apids"] += 1

            # Decode payload structures
            decoded_content = decode_payload(apid, payload_bytes)
            
            # Append context along with parsed data fields
            extracted_data[mnemonic].append({
                "Sequence_Count": sequence_count,
                "Payload_Size_Bytes": payload_length,
                "Data": decoded_content
            })
            
            metrics["valid_packets"] += 1
            # Advance cursor completely past this valid packet framework
            cursor = asm_index + total_packet_length
        else:
            # Found ASM but the following data failed core CCSDS version layout checks
            metrics["corrupted_frames"] += 1
            cursor = asm_index + 4  # Advance past ASM and keep tracking

    print(f"\nProcessing Complete. Results:")
    print(f" -> Valid packets extracted: {metrics['valid_packets']}")
    print(f" -> ASM patterns flagged as corrupted or noisy: {metrics['corrupted_frames']}")
    print(f" -> Packets with unknown/corrupted APIDs: {metrics['unknown_apids']}")
    
    return extracted_data


# --- Execution Hook ---
if __name__ == "__main__":
    # Replace with the path to your actual binary file
    telemetry_output = process_noisy_asm_stream("capture.bin")

    
# parsing methods for data
    if telemetry_output["HK_NOMINAL"]:
        for i in telemetry_output["HK_NOMINAL"]:
            print(f"{i}")
#            print(f"{i['Data']['Status_Flags']}")
    if telemetry_output["SYSLOG"]:
        for i in telemetry_output["SYSLOG"]:
            print(f"{i}")

    if telemetry_output["ADCS_STATUS"]:
        for i in telemetry_output["ADCS_STATUS"]:
#            print(f"{i}")
            print(f"{i['Data']['Raw_Bytes_Hex']}")







